package com.rpsbattle.tournament;
import com.rpsbattle.account.*;import com.rpsbattle.account.domain.*;import com.rpsbattle.auth.AuthService;import com.rpsbattle.tournament.domain.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class ParticipantDisputeTest {
 @Test void ownReportUsesExistingAuditAndReviewWithoutChangingWinnerAndCannotBeRepeated(){
  var now=Instant.now();var user=new User(UserId.random(),"reporter","reporter@example.invalid","fixture","Reporter",UserRole.USER,AccountStatus.ACTIVE,now,now,null,0);var auth=AuthService.sessionAuthentication(user);var accounts=mock(AccountAuthorizationService.class);when(accounts.requireUser(auth)).thenReturn(user);var tournaments=mock(TournamentService.class);var owned=mock(OwnedTournamentService.class);doAnswer(invocation->{((Runnable)invocation.getArgument(1)).run();return null;}).when(owned).systemMutation(any(),any());
  var t=new Tournament("cup","Cup",TournamentFormat.ROUND_ROBIN,now);t.status=TournamentStatus.RUNNING;var a=new TournamentParticipant("a",null,"","A",1,user.id().value());var b=new TournamentParticipant("b",null,"","B",2,UUID.randomUUID());var m=new TournamentMatch("match",t.id,a,b);m.status=TournamentMatch.Status.FINISHED;m.finishedAt=now;m.winnerParticipantId="b";m.result="WIN";t.matches.add(m);when(tournaments.find(t.id)).thenReturn(t);var service=new ParticipantDisputeService(accounts,tournaments,owned,Clock.fixed(now.plusSeconds(1),ZoneOffset.UTC),24);
  service.report(auth,t.id,m.id,"RESULT","Please review this match");assertThat(t.status).isEqualTo(TournamentStatus.PAUSED);assertThat(t.operations.reviews()).containsKey(m.id);assertThat(t.operations.audit().getLast().type()).isEqualTo("MATCH_REVIEW_REQUESTED");assertThat(m.winnerParticipantId).isEqualTo("b");assertThat(m.status).isEqualTo(TournamentMatch.Status.FINISHED);assertThatThrownBy(()->service.report(auth,t.id,m.id,"RESULT","Again")).hasMessage("DISPUTE_ALREADY_REPORTED");assertThat(service.list(auth,t.id).toString()).contains("OPEN","canReport=false");
  t.operations=t.operations.review(m.id,null);TournamentAudit.append(t,"MATCH_REVIEW_REJECTED",UUID.randomUUID(),m.id,"Evidence reviewed",null,null);assertThat(service.list(auth,t.id).toString()).contains("REJECTED");assertThatThrownBy(()->service.report(auth,t.id,m.id,"RESULT","Again")).hasMessage("DISPUTE_ALREADY_REPORTED");
  var expired=new ParticipantDisputeService(accounts,tournaments,owned,Clock.fixed(now.plus(Duration.ofHours(24)),ZoneOffset.UTC),24);assertThatThrownBy(()->expired.report(auth,t.id,m.id,"NETWORK","Late report")).hasMessage("DISPUTE_WINDOW_CLOSED");
  var foreign=new TournamentMatch("foreign",t.id,b,b);foreign.status=TournamentMatch.Status.FINISHED;foreign.finishedAt=now;t.matches.add(foreign);assertThatThrownBy(()->service.report(auth,t.id,foreign.id,"OTHER","Foreign match")).hasMessage("TOURNAMENT_FORBIDDEN");assertThatThrownBy(()->service.report(auth,t.id,m.id,"override","winner=a")).hasMessage("INVALID_DISPUTE");
 }
}
